#pragma once#include <string>#include <map>enum EMBRawType{  mbWord,  mbInt16,  mbInt32,  mbFloat,  mbByte,  mbDouble,  mbBit,};enum EModelType{  modelEmpty,  modelInt32,  modelDouble64,  modelByte,};struct SPointInfo{  SPointInfo() : mbAddress( -1 ), mbType( mbWord ), mbSize( 1 ), pInt( NULL ), modelType( modelEmpty )  {}  WORD mbAddress;  EMBRawType mbType;  BYTE mbSize;  union  {//поле модели    int* pInt;    BYTE* pByte;    double* pDouble;  };  EModelType modelType;  std::string szModelAddress;};typedef std::map<WORD, SPointInfo> tConnectInfo_;